sys_script.script:
(function executeRule(current, previous) {

    var patientId = current.getValue('patient');
    var notificationType = current.getValue('notification_type');
    var channel = current.getValue('channel');
    var subject = current.getValue('subject');
    var recipient = current.getValue('recipient');

    // Do not perform duplicate checking until the key fields exist.
    if (
        gs.nil(patientId) ||
        gs.nil(notificationType) ||
        gs.nil(channel) ||
        gs.nil(subject) ||
        gs.nil(recipient)
    ) {
        return;
    }

    var duplicate = new GlideRecord(
        'x_2130921_caresy_0_notification_log'
    );

    duplicate.addQuery('patient', patientId);
    duplicate.addQuery('notification_type', notificationType);
    duplicate.addQuery('channel', channel);
    duplicate.addQuery('subject', subject);
    duplicate.addQuery('recipient', recipient);
    duplicate.addQuery('active', true);

    // Exclude the current record during Update.
    if (!current.isNewRecord()) {
        duplicate.addQuery('sys_id', '!=', current.getUniqueValue());
    }

    duplicate.setLimit(1);
    duplicate.query();

    if (duplicate.next()) {

        gs.addErrorMessage(
            'A duplicate active notification already exists for this Patient, Notification Type, Channel, Subject, and Recipient.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
